window.FC={"subjects":[{"id":"nav","name":"Navigation","topics":[{"id":"nav-earth-convergence-departure","name":"Earth, Convergence & Departure"},{"id":"nav-chart-scale","name":"Chart Scale"},{"id":"nav-map-projections","name":"Map Projections"},{"id":"nav-compass-direction","name":"Compass & Direction"},{"id":"nav-units-conversions","name":"Units & Conversions"},{"id":"nav-wind-triangle-drift","name":"Wind Triangle & Drift"},{"id":"nav-simple-navigation-maths","name":"Simple Navigation Maths"},{"id":"nav-1-in-60-rule-bearings","name":"1 in 60 Rule & Bearings"},{"id":"nav-solar-system-time","name":"Solar System & Time"},{"id":"nav-descent-planning","name":"Descent Planning"},{"id":"nav-critical-point-pnr","name":"Critical Point & PNR"},{"id":"nav-payload-fuel-weight-and-bala","name":"Payload, Fuel & Weight and Balance"},{"id":"nav-flight-plan-icao","name":"Flight Plan (ICAO)"},{"id":"nav-aeroplane-performance","name":"Aeroplane Performance"}]},{"id":"met","name":"Meteorology","topics":[{"id":"met-atmosphere-isa","name":"Atmosphere & ISA"},{"id":"met-pressure-altimetry","name":"Pressure & Altimetry"},{"id":"met-temperature-humidity-cloud-b","name":"Temperature, Humidity & Cloud Base"},{"id":"met-stability-adiabatics","name":"Stability & Adiabatics"},{"id":"met-pressure-systems-depressions","name":"Pressure Systems & Depressions"},{"id":"met-winds-upper-winds","name":"Winds & Upper Winds"},{"id":"met-jet-streams","name":"Jet Streams"},{"id":"met-clouds-fog-precipitation","name":"Clouds, Fog & Precipitation"},{"id":"met-fronts-air-masses","name":"Fronts & Air Masses"},{"id":"met-thunderstorms-turbulence-win","name":"Thunderstorms, Turbulence & Windshear"},{"id":"met-icing","name":"Icing"},{"id":"met-tropical-cyclones","name":"Tropical Cyclones"},{"id":"met-climatology-monsoon","name":"Climatology & Monsoon"},{"id":"met-weather-reports-charts","name":"Weather Reports & Charts"},{"id":"met-meteorological-calculations","name":"Meteorological Calculations"}]},{"id":"reg","name":"Regulations","topics":[{"id":"reg-icao-annexes-conventions","name":"ICAO, Annexes & Conventions"},{"id":"reg-aircraft-act-rules-dgca","name":"Aircraft Act, Rules & DGCA"},{"id":"reg-registration-airworthiness","name":"Registration & Airworthiness"},{"id":"reg-licensing-medical","name":"Licensing & Medical"},{"id":"reg-rules-of-the-air","name":"Rules of the Air"},{"id":"reg-air-traffic-services","name":"Air Traffic Services"},{"id":"reg-aerodromes-lighting-marking","name":"Aerodromes, Lighting & Marking"},{"id":"reg-distress-emergency-communica","name":"Distress, Emergency & Communications"},{"id":"reg-accidents-incidents-security","name":"Accidents, Incidents & Security"},{"id":"reg-operations-crew-public-healt","name":"Operations, Crew & Public Health"},{"id":"reg-human-performance-limitation","name":"Human Performance & Limitations"},{"id":"reg-charges-documents-other","name":"Charges, Documents & Other"}]},{"id":"tec","name":"Technical General","topics":[{"id":"tec-aerodynamics-performance","name":"Aerodynamics & Performance"},{"id":"tec-flight-controls-stability","name":"Flight Controls & Stability"},{"id":"tec-airframe-structures","name":"Airframe & Structures"},{"id":"tec-powerplant","name":"Powerplant"},{"id":"tec-propellers","name":"Propellers"},{"id":"tec-aircraft-systems","name":"Aircraft Systems"},{"id":"tec-pitot-statics","name":"Pitot Statics"},{"id":"tec-barometric-altimeters","name":"Barometric Altimeters"},{"id":"tec-radio-altimeters","name":"Radio Altimeters"},{"id":"tec-vertical-speed-indicators-vs","name":"Vertical Speed Indicators (VSI)"},{"id":"tec-airspeed-indicators","name":"Airspeed Indicators"},{"id":"tec-airspeeds","name":"Airspeeds"},{"id":"tec-mach","name":"Mach"},{"id":"tec-gyroscope","name":"Gyroscope"},{"id":"tec-attitude-indicators","name":"Attitude Indicators"},{"id":"tec-turn-and-slip","name":"Turn and Slip"},{"id":"tec-ins-irs-and-fms","name":"INS, IRS and FMS"},{"id":"tec-efis","name":"EFIS"},{"id":"tec-autoflight","name":"Autoflight"},{"id":"tec-flight-director","name":"Flight Director"},{"id":"tec-eicas-ecam","name":"EICAS / ECAM"},{"id":"tec-engine-instruments","name":"Engine Instruments"},{"id":"tec-temperature-indicators","name":"Temperature Indicators"},{"id":"tec-fuel-systems","name":"Fuel Systems"},{"id":"tec-compass","name":"Compass"},{"id":"tec-warning-recording-systems","name":"Warning & Recording Systems"},{"id":"tec-tcas","name":"TCAS"}]}],"cards":[{"t":"nav-earth-convergence-departure","f":"What shape is the Earth, and what numbers do you need for navigation?","a":"An oblate spheroid, slightly flattened at the poles. For most calculations treat it as a sphere.","l":["<b>1 minute of latitude = 1 NM</b> (1852 m)","Circumference ≈ 360 × 60 = 21 600 NM","The polar diameter is about 43 km (23 NM) shorter than the equatorial one"],"id":"c13d1e887","s":"nav"},{"t":"nav-earth-convergence-departure","f":"What is a great circle, and why do pilots care?","a":"A circle on the surface whose plane passes through the centre of the Earth. The <b>shortest distance</b> between two points lies along it.","l":["The equator and every meridian (with its opposite) are great circles","Every other parallel is a small circle","A great circle crosses successive meridians at different angles, so the track keeps changing"],"d":"rhumb","id":"cfa941f44","s":"nav"},{"t":"nav-earth-convergence-departure","f":"Rhumb line or great circle: how do they differ?","a":"A <b>rhumb line</b> cuts every meridian at the same angle (constant true track). A <b>great circle</b> is the shortest route.","l":["A rhumb line is longer, except along a meridian or the equator","In the northern hemisphere the great circle lies poleward of the rhumb line","On a Mercator chart the rhumb line is straight and the great circle is a curve"],"tip":"Constant track = rhumb. Shortest distance = great circle.","id":"c147bd359","s":"nav"},{"t":"nav-earth-convergence-departure","f":"Define convergence and give the formula.","a":"The angle between two meridians at a given latitude: how much a great-circle track changes direction relative to the meridians.","l":["Zero at the equator, equal to the change of longitude at the pole","Example: Δλ = 20° at 45°N gives 20 × sin 45° ≈ 14°"],"m":["\\text{Convergence}=\\Delta\\lambda\\times\\sin(\\text{mean latitude})"],"d":"conv","id":"c4f90b6d9","s":"nav"},{"t":"nav-earth-convergence-departure","f":"What is departure, and how do you work it out?","a":"The distance in nautical miles along a parallel between two meridians.","l":["1° of longitude is 60 NM at the equator, shrinking to 0 at the poles","Example: 2° at 60°N is 120′ × cos 60° = 60 NM"],"m":["\\text{Departure}=\\Delta\\lambda\\ (\\text{minutes of arc})\\times\\cos(\\text{latitude})"],"id":"c9628b08f","s":"nav"},{"t":"nav-earth-convergence-departure","f":"What is the conversion angle?","a":"The angle between the rhumb-line track and the great-circle track at the start or end of a leg. It is <b>half the convergence</b>.","m":["\\text{Conversion angle}=\\tfrac12\\,\\Delta\\lambda\\,\\sin(\\text{mean latitude})"],"tip":"Use it to convert a great-circle bearing into a rhumb-line bearing for plotting on a Mercator chart.","id":"c817a4dda","s":"nav"},{"t":"nav-earth-convergence-departure","f":"How long is one degree of longitude at 40°N?","a":"About <b>46 NM</b>.","l":["Cosine of latitude shrinks east–west distance as you go north"],"m":["60\\ \\text{NM}\\times\\cos 40^\\circ\\approx 46\\ \\text{NM}"],"id":"cb291ba30","s":"nav"},{"t":"nav-chart-scale","f":"How do you calculate chart scale?","a":"Scale (representative fraction) is chart length divided by the real distance, both in the same unit.","l":["1 : 1 000 000 means 1 cm on the chart is 10 km on the ground (5.4 NM)","Larger denominator = smaller scale = less detail"],"m":["\\text{Scale}=\\frac{\\text{chart length}}{\\text{earth distance}}"],"d":"scale","id":"c301d85f4","s":"nav"},{"t":"nav-chart-scale","f":"On a 1 : 500 000 chart, how many NM is 1 cm?","a":"<b>2.7 NM</b> (1 cm = 5 km = 5000 m ÷ 1852).","tip":"Chart length × scale denominator = ground length. Convert to NM at the end.","id":"c0c74d25d","s":"nav"},{"t":"nav-chart-scale","f":"How does scale vary on a Mercator chart?","a":"Scale increases with latitude. At latitude φ it equals the equatorial scale multiplied by <b>sec φ</b>.","l":["Measure distance against the latitude scale at the same latitude as the leg"],"m":["\\text{Scale at }\\phi=\\frac{\\text{scale at equator}}{\\cos\\phi}"],"id":"c44d94c98","s":"nav"},{"t":"nav-map-projections","f":"Properties of the Mercator projection?","a":"A cylindrical, conformal (orthomorphic) projection.","l":["Meridians are equally spaced parallel straight lines","Parallels are straight and spaced further apart towards the poles","Rhumb lines are straight; great circles curve towards the equator-side (convex to the pole)","The poles cannot be shown; scale grows with latitude"],"id":"c23d47cbb","s":"nav"},{"t":"nav-map-projections","f":"Why is the Lambert conformal conic popular for aeronautical charts?","a":"Great circles are nearly straight lines and scale is almost constant across the chart.","l":["Two standard parallels where scale is exact","Scale is contracted between them and expanded outside","Meridians are straight lines that converge; parallels are arcs of circles","Convergence factor (constant of the cone) ≈ sin of the parallel of origin"],"m":["n=\\sin\\phi_0"],"id":"cffa0ed4e","s":"nav"},{"t":"nav-map-projections","f":"What does “conformal” (orthomorphic) mean?","a":"Angles are preserved. Scale is the same in every direction at a point, and meridians and parallels cross at right angles.","tip":"Needed so that bearings measured on the chart are correct.","id":"c88bdc42e","s":"nav"},{"t":"nav-map-projections","f":"Which projection do you use near the poles?","a":"A <b>polar stereographic</b> projection (azimuthal and conformal).","l":["Great circles through the centre are straight lines","Meridians radiate from the pole as straight lines"],"id":"c5e8de048","s":"nav"},{"t":"nav-compass-direction","f":"From true to compass: what is the order?","a":"<b>T</b>rue → (variation) → <b>M</b>agnetic → (deviation) → <b>C</b>ompass.","l":["Variation east, magnetic least. Variation west, magnetic best","Variation depends on location, deviation on the aircraft and its heading"],"d":"tvmdc","tip":"“True Virgins Make Dull Company”, adding West, subtracting East when going from true to magnetic.","id":"c03349a27","s":"nav"},{"t":"nav-compass-direction","f":"Isogonals, agonic lines and isoclinals?","a":"<b>Isogonal</b>: joins places of equal variation. <b>Agonic line</b>: zero variation. <b>Isoclinal</b>: equal dip. <b>Aclinic line</b>: zero dip (magnetic equator).","id":"cd6ddc574","s":"nav"},{"t":"nav-compass-direction","f":"How do you convert a relative bearing to a true bearing?","a":"Add the relative bearing to the true heading.","l":["Subtract 360° if the answer is above 360°","Reciprocal = ±180°"],"m":["\\text{True bearing}=\\text{True heading}+\\text{relative bearing}"],"id":"c8f2b9a82","s":"nav"},{"t":"nav-compass-direction","f":"What is grivation?","a":"The angle between <b>grid north</b> and <b>magnetic north</b>.","l":["Used with grid navigation near the poles, where meridians converge rapidly","Grid heading = true heading − grid convergence (sign depends on the side of the grid meridian)"],"id":"c2f3e2844","s":"nav"},{"t":"nav-units-conversions","f":"Key distance and speed conversions to remember?","a":"Know these cold:","l":["1 NM = 1852 m = 6076 ft","1 SM = 1609 m = 5280 ft","1 m = 3.281 ft · 1 ft = 0.3048 m","1 kt = 1.852 km/h","1 inHg = 33.86 hPa"],"id":"c6ec38297","s":"nav"},{"t":"nav-units-conversions","f":"Mass, volume and fuel conversions?","a":"Quick table:","l":["1 kg = 2.205 lb","1 US gallon = 3.785 L · 1 Imp gallon = 4.546 L","Avgas density ≈ 0.72 kg/L","Jet A-1 density ≈ 0.80 kg/L"],"m":["\\text{mass}=\\text{volume}\\times\\text{density}"],"tip":"Always check the unit of fuel on the question: litres, US gallons or kg.","id":"c9b84beb9","s":"nav"},{"t":"nav-units-conversions","f":"Speed, distance, time: the formulas?","a":"Keep minutes and hours straight.","l":["GS 120 kt means 2 NM per minute","GS 180 kt means 3 NM per minute"],"m":["D=S\\times T","T(\\text{min})=\\frac{D(\\text{NM})}{GS(\\text{kt})}\\times 60"],"id":"c4cdbe06d","s":"nav"},{"t":"nav-wind-triangle-drift","f":"What are the six quantities in the wind triangle?","a":"Heading and TAS, track and ground speed, wind direction and speed.","l":["The vectors close: heading + wind = track","<b>Drift</b> is the angle between heading and track","<b>WCA</b> (wind correction angle) is the heading change needed to hold track: WCA = −drift","Wind direction is always where it blows <i>from</i>"],"d":"wtri","id":"c249eacf8","s":"nav"},{"t":"nav-wind-triangle-drift","f":"How do you calculate the wind correction angle?","a":"Use the sine rule on the wind triangle.","l":["Small angles: WCA ≈ 60 × crosswind ÷ TAS (degrees)","Wind from the right means crab right, so heading is to the right of track"],"m":["\\sin(\\text{WCA})=\\frac{W}{TAS}\\,\\sin(\\text{angle between track and wind})"],"id":"c5f499668","s":"nav"},{"t":"nav-wind-triangle-drift","f":"How do you find headwind and crosswind components?","a":"Resolve the wind against the runway or track.","l":["θ is the angle between wind direction and runway heading (or track)","Example: 30 kt at 40° off: crosswind 19 kt, headwind 23 kt"],"m":["\\text{Crosswind}=V\\sin\\theta","\\text{Headwind}=V\\cos\\theta"],"d":"xcomp","id":"cd757cdb3","s":"nav"},{"t":"nav-wind-triangle-drift","f":"The clock method for crosswind in your head?","a":"Use fractions of the wind speed by angle off the runway:","l":["15° → ¼ of the wind speed","30° → ½","45° → ¾","60° or more → all of it"],"tip":"For headwind use the opposite fractions: 60°→ ½, 30°→ ⅞ roughly.","id":"cc5edee1e","s":"nav"},{"t":"nav-wind-triangle-drift","f":"GS from TAS and wind: a quick estimate?","a":"Ground speed ≈ TAS − headwind component (or + tailwind).","l":["Direct headwind of 30 kt at TAS 150 kt gives GS 120 kt","A pure crosswind changes GS very little, mainly the drift"],"id":"cd24bb022","s":"nav"},{"t":"nav-simple-navigation-maths","f":"Convert a climb or descent gradient into a rate of climb.","a":"Rate of climb in ft/min depends on gradient and ground speed.","l":["5 % gradient at 120 kt ≈ 600 ft/min","ft per NM = ROC ÷ GS × 60"],"m":["ROC(\\text{ft/min})\\approx GS(\\text{kt})\\times\\text{gradient}(\\%)\\times 1.013"],"d":"climb","id":"c09deb6fe","s":"nav"},{"t":"nav-simple-navigation-maths","f":"Gradient in percent from the angle?","a":"Percent gradient is 100 × tan of the angle.","l":["3° ≈ 5.2 % ≈ 318 ft per NM","1° ≈ 1.75 % ≈ 106 ft per NM"],"m":["\\text{gradient}\\ (\\%)=100\\tan\\theta"],"id":"c6529bddf","s":"nav"},{"t":"nav-simple-navigation-maths","f":"Fuel, time and distance: how do you solve “how much fuel for this leg”?","a":"Time first, then fuel.","l":["Use the leg’s ground speed, not TAS","Add reserve according to the rules in the question"],"m":["\\text{fuel}=\\text{fuel flow}\\times\\frac{\\text{distance}}{GS}"],"id":"ca3e8215c","s":"nav"},{"t":"nav-1-in-60-rule-bearings","f":"State the 1 in 60 rule.","a":"At 60 NM from the point of departure, 1° of track error gives 1 NM of lateral displacement. Distances scale in proportion.","m":["\\text{Track error}^\\circ=\\frac{\\text{off-track distance}}{\\text{distance flown}}\\times 60"],"d":"p60","id":"c345a6685","s":"nav"},{"t":"nav-1-in-60-rule-bearings","f":"How do you regain track using 1 in 60?","a":"Add the <b>track error</b> and the <b>closing angle</b>.","l":["To rejoin track in the same distance you have already flown, alter heading by <b>twice</b> the track error","Turn the correct way: towards the track"],"m":["\\text{Closing angle}=\\frac{\\text{off-track}}{\\text{distance to go}}\\times 60"],"id":"cdfd9282b","s":"nav"},{"t":"nav-1-in-60-rule-bearings","f":"QDM, QDR, QUJ and QTE?","a":"The Q-codes for bearings:","l":["<b>QDM</b>: magnetic bearing <i>to</i> the station","<b>QDR</b>: magnetic bearing <i>from</i> the station","<b>QUJ</b>: true bearing <i>to</i> the station","<b>QTE</b>: true bearing <i>from</i> the station"],"tip":"QDM and QDR differ by 180°, as do QUJ and QTE.","id":"c1dbcc46f","s":"nav"},{"t":"nav-1-in-60-rule-bearings","f":"Time to a station from a bearing change?","a":"Fly at a steady speed on a track passing abeam, note the time for a given bearing change.","l":["Valid when the bearing change is measured at the wingtip or on the beam","Distance = ground speed × time"],"m":["\\text{Time to station (min)}=\\frac{60\\times\\text{time between bearings (min)}}{\\text{change of bearing (}^\\circ)}"],"id":"c6bfbbeee","s":"nav"},{"t":"nav-solar-system-time","f":"How do longitude and time relate?","a":"The Earth turns 360° in 24 h, so <b>15° = 1 hour</b> and <b>1° = 4 minutes</b>.","l":["East is later (add), west is earlier (subtract)","IST = UTC + 5 h 30 min, based on 82.5° E"],"m":["\\text{LMT}=\\text{UTC}+\\frac{\\text{longitude E}}{15}"],"id":"cd15e9496","s":"nav"},{"t":"nav-solar-system-time","f":"What are civil, nautical and astronomical twilight?","a":"Defined by how far the centre of the Sun is below the horizon:","l":["<b>Civil</b>: 6° below","<b>Nautical</b>: 12° below","<b>Astronomical</b>: 18° below"],"id":"cb7295ace","s":"nav"},{"t":"nav-solar-system-time","f":"Why do we have seasons, and where are the tropics?","a":"The Earth’s axis is tilted about 23.5° to the orbit plane.","l":["Tropic of Cancer 23.5° N, Tropic of Capricorn 23.5° S","Arctic and Antarctic circles at 66.5°","Equinoxes about 21 March and 23 September; solstices about 21 June and 22 December","Earth is closest to the Sun (perihelion) in early January"],"id":"cd8bf8615","s":"nav"},{"t":"nav-solar-system-time","f":"Crossing the International Date Line?","a":"It follows 180° longitude. Going <b>east</b> you repeat a day (date goes back one); going <b>west</b> you skip a day (date goes forward).","tip":"East = lose nothing on the clock but gain a date: subtract a day.","id":"cd4a08169","s":"nav"},{"t":"nav-descent-planning","f":"How far before the destination should you start a descent?","a":"Use the 3-to-1 rule for a 3° path.","l":["From FL 330 down to 3000 ft: 30 000 ft ÷ 1000 × 3 = 90 NM","Add distance to slow down, and allow for wind"],"m":["D(\\text{NM})\\approx\\frac{\\Delta h(\\text{ft})}{1000}\\times 3"],"d":"desc","id":"c4e3988c8","s":"nav"},{"t":"nav-descent-planning","f":"What rate of descent holds a 3° path?","a":"About 5 times the ground speed (more precisely 5.3 ×).","l":["GS 140 kt → ROD ≈ 700 ft/min","A tailwind raises GS and needs a higher rate"],"m":["ROD(\\text{ft/min})\\approx GS(\\text{kt})\\times 5"],"id":"cb82d8434","s":"nav"},{"t":"nav-descent-planning","f":"Descent gradient from rate and speed?","a":"ft per NM = rate of descent ÷ ground speed × 60.","l":["1000 ft/min at 120 kt = 500 ft/NM (too steep for a 3° path)"],"m":["\\text{ft/NM}=\\frac{ROD}{GS}\\times 60"],"id":"caa8476d1","s":"nav"},{"t":"nav-critical-point-pnr","f":"What is the critical point (CP) or equal time point (ETP)?","a":"The point on a route from which the flight time to continue to the destination equals the time to return to the departure (or alternate) airfield.","l":["D is the whole distance between the two airfields","The CP moves <b>into the wind</b>"],"m":["\\text{Distance to CP}=\\frac{D\\times GS_{back}}{GS_{out}+GS_{back}}","\\text{Time to CP}=\\frac{D}{GS_{out}+GS_{back}}"],"d":{"k":"pet","D":600,"go":140,"gh":110},"id":"c0c450798","s":"nav"},{"t":"nav-critical-point-pnr","f":"What is the point of no return (PNR)?","a":"The last point from which you can still return to the departure aerodrome using the fuel carried (safe endurance <i>E</i>).","l":["Based on fuel, whereas CP is based on time","A tailwind outbound brings the PNR further out"],"m":["\\text{Time to PNR}=\\frac{E\\times GS_{back}}{GS_{out}+GS_{back}}","\\text{Distance to PNR}=GS_{out}\\times\\text{time to PNR}"],"d":{"k":"pnr","go":140,"gh":110,"E":4},"id":"c152f0fcf","s":"nav"},{"t":"nav-critical-point-pnr","f":"CP versus PNR: what is the difference?","a":"<b>CP</b>: equal time to two airfields. <b>PNR</b>: last point of return using fuel.","l":["CP depends only on speeds and distance","PNR depends on safe endurance as well","Both are worked with outbound and homebound ground speeds"],"id":"c34473105","s":"nav"},{"t":"nav-payload-fuel-weight-and-bala","f":"How do you find the centre of gravity?","a":"Take moments about a datum and divide by total mass.","l":["Moment = mass × arm","Arm is measured from the datum, positive aft","Check the CG lies inside the envelope for every loading"],"m":["\\text{CG}=\\frac{\\sum(\\text{mass}\\times\\text{arm})}{\\sum\\text{mass}}"],"d":"cgbeam","id":"ce28c5a70","s":"nav"},{"t":"nav-payload-fuel-weight-and-bala","f":"How far does the CG move when you shift cargo?","a":"The shift equals mass moved times distance moved, over total mass.","l":["Moving mass aft moves the CG aft; forward moves it forward","The shift is always in the direction the mass moved"],"m":["\\text{CG shift}=\\frac{m_{moved}\\times d}{M_{total}}"],"id":"c847c459f","s":"nav"},{"t":"nav-payload-fuel-weight-and-bala","f":"Aircraft mass terms in order?","a":"Build up from the empty aircraft:","l":["<b>Basic empty mass</b> (structure, systems, unusable fuel)","<b>Operating empty mass</b> = basic empty + crew, catering, fluids","<b>Zero fuel mass</b> = operating empty + payload","<b>Take-off mass</b> = zero fuel + fuel","<b>Landing mass</b> = take-off mass − trip fuel"],"tip":"Each has a maximum: MZFM, MTOM (structural or performance limited), MLM.","id":"c14a778b9","s":"nav"},{"t":"nav-payload-fuel-weight-and-bala","f":"What does an aft or forward CG do to handling?","a":"A <b>forward</b> CG makes the aircraft more stable but nose-heavy; an <b>aft</b> CG makes it less stable.","l":["Forward CG: higher stall speed, more trim drag and fuel burn, heavier elevator forces","Aft CG: lower stall speed, longer range, but reduced stability and recovery risk","Beyond the aft limit the aircraft may be impossible to recover from a stall"],"id":"c7ae6222d","s":"nav"},{"t":"nav-payload-fuel-weight-and-bala","f":"What is included in the fuel plan for a flight?","a":"ICAO Annex 6 requires taxi, trip, contingency, alternate and final reserve fuel.","l":["Contingency: typically 5 % of trip fuel","Alternate: to the destination alternate","Final reserve: 30 min for turbine engines (at holding speed, 1500 ft above the aerodrome) or 45 min for piston engines","Extra fuel at the commander’s discretion"],"id":"c20923c7e","s":"nav"},{"t":"nav-flight-plan-icao","f":"What goes in the ICAO flight plan form?","a":"The main items of the FPL:","l":["<b>7</b> aircraft identification","<b>8</b> flight rules and type of flight","<b>9</b> number, type, wake turbulence category","<b>10</b> equipment and surveillance","<b>13</b> departure aerodrome and time","<b>15</b> cruise speed, level and route","<b>16</b> destination, EET, alternates","<b>18</b> other information","<b>19</b> endurance, persons on board, survival equipment"],"id":"ca2372345","s":"nav"},{"t":"nav-flight-plan-icao","f":"Flight rules and type of flight letters?","a":"Item 8 letters:","l":["<b>I</b> IFR · <b>V</b> VFR","<b>Y</b> IFR first, then changes to VFR","<b>Z</b> VFR first, then changes to IFR","<b>S</b> scheduled · <b>N</b> non-scheduled · <b>G</b> general aviation · <b>M</b> military · <b>X</b> other"],"id":"cb75668d9","s":"nav"},{"t":"nav-flight-plan-icao","f":"Wake turbulence categories in the flight plan?","a":"By maximum take-off mass:","l":["<b>L</b> light: up to 7 000 kg","<b>M</b> medium: 7 000 to 136 000 kg","<b>H</b> heavy: 136 000 kg and above","<b>J</b> super (A380)"],"id":"c53283d4a","s":"nav"},{"t":"nav-aeroplane-performance","f":"V1, VR and V2: what do they mean?","a":"Take-off speeds for a multi-engine transport aeroplane:","l":["<b>V1</b>: decision speed. Before it, reject; after it, continue","<b>VR</b>: rotation speed, pilot begins to raise the nose","<b>V2</b>: take-off safety speed, reached by 35 ft with one engine failed","VR is not lower than V1; V1 not lower than VMCG"],"id":"c7df586e9","s":"nav"},{"t":"nav-aeroplane-performance","f":"TORA, TODA, ASDA and LDA?","a":"Declared distances of a runway:","l":["<b>TORA</b>: take-off run available","<b>TODA</b> = TORA + clearway","<b>ASDA</b> = TORA + stopway","<b>LDA</b>: landing distance available"],"tip":"Clearway cannot be longer than half the TORA.","id":"c8bb9a9dd","s":"nav"},{"t":"nav-aeroplane-performance","f":"What lengthens the take-off distance?","a":"Higher mass, temperature, elevation, tailwind, up-slope, wet or soft surface, and flap setting that is too low.","l":["Headwind shortens the take-off","Higher density altitude means less thrust and higher true speed"],"id":"cb949ee82","s":"nav"},{"t":"nav-aeroplane-performance","f":"Vx and Vy: which speed gives what?","a":"<b>Vx</b> gives the best <i>angle</i> of climb (obstacle clearance). <b>Vy</b> gives the best <i>rate</i> of climb (time to height).","l":["Vx is slower than Vy","The two converge as altitude increases and meet at the absolute ceiling","Service ceiling: rate of climb of 100 ft/min (propeller) or 500 ft/min (jet)"],"id":"c292a5d1e","s":"nav"},{"t":"met-atmosphere-isa","f":"What are the ISA values at mean sea level and how does temperature change with height?","a":"Temperature 15 °C, pressure 1013.25 hPa, density 1.225 kg/m³.","l":["Falls 6.5 °C per km (≈ 1.98 °C per 1000 ft) up to the tropopause at 11 km (36 090 ft)","Constant −56.5 °C from 11 km to 20 km","Then rises 1 °C per km up to 32 km"],"d":"isa","id":"cd2e6a10c","s":"met"},{"t":"met-atmosphere-isa","f":"What is the make-up of the atmosphere?","a":"About 78 % nitrogen, 21 % oxygen, 0.9 % argon, 0.04 % carbon dioxide, plus water vapour (0–4 %).","l":["The mix is the same to about 80 km, apart from water vapour and ozone","Most water vapour and all weather lie in the troposphere"],"id":"cd6fd7f50","s":"met"},{"t":"met-atmosphere-isa","f":"Where is the tropopause and why does it matter?","a":"The boundary between troposphere and stratosphere, where temperature stops falling.","l":["About 16–17 km at the equator, 8–9 km at the poles, 11 km in ISA","Higher in summer than winter, and over warm air","Jet streams, clear-air turbulence and cirrus gather near it"],"id":"c31e0434d","s":"met"},{"t":"met-atmosphere-isa","f":"Which flight levels match the standard pressure levels?","a":"Approximate pressure-altitude values:","l":["850 hPa ≈ FL 050","700 hPa ≈ FL 100","500 hPa ≈ FL 180","300 hPa ≈ FL 300","250 hPa ≈ FL 340","200 hPa ≈ FL 390"],"tip":"Pressure halves about every 18 000 ft (5.5 km).","id":"c68768453","s":"met"},{"t":"met-atmosphere-isa","f":"How is air density calculated?","a":"From the equation of state for dry air.","l":["Density falls with height and with higher temperature","Humid air is less dense than dry air (water vapour is lighter than N₂ and O₂)"],"m":["\\rho=\\frac{p}{R\\,T}\\qquad R=287\\ \\text{J\\,kg}^{-1}\\text{K}^{-1}"],"id":"c2d3e47e9","s":"met"},{"t":"met-atmosphere-isa","f":"How many feet is one hPa near the surface?","a":"About <b>27–30 ft per hPa</b>. Exam questions normally use 30 ft.","l":["Gets bigger with height (about 50 ft per hPa at 18 000 ft)","Used for QFE/QNH and pressure altitude calculations"],"id":"c33b051f3","s":"met"},{"t":"met-pressure-altimetry","f":"QNH, QFE and QNE: what does the altimeter read?","a":"It depends on the subscale setting:","l":["<b>QNH</b>: altitude above mean sea level (reads aerodrome elevation on the ground)","<b>QFE</b>: height above the aerodrome (reads zero on the runway)","<b>QNE / 1013.25</b>: pressure altitude, used for flight levels"],"d":"qnh","id":"ccbb2031b","s":"met"},{"t":"met-pressure-altimetry","f":"Flying from high pressure to low pressure without resetting: what happens?","a":"The altimeter <b>over-reads</b>: the aircraft is lower than indicated. “High to low, look out below.”","l":["Each 1 hPa of error ≈ 30 ft","Flying from warm to cold air gives the same effect","Low to high pressure is the safe way round (altimeter under-reads)"],"id":"c9402752f","s":"met"},{"t":"met-pressure-altimetry","f":"How do you find pressure altitude?","a":"Correct the elevation for the difference between 1013 hPa and the QNH.","l":["QNH 1003 hPa at elevation 500 ft gives PA = 500 + 300 = 800 ft"],"m":["PA=\\text{elevation}+(1013-QNH)\\times 30\\ \\text{ft}"],"id":"cc1258833","s":"met"},{"t":"met-pressure-altimetry","f":"What temperature correction applies to an altimeter?","a":"True altitude differs from indicated by about <b>4 ft per 1000 ft per °C</b> of ISA deviation.","l":["Colder than ISA: true altitude is lower than indicated (dangerous over high ground)","Warmer than ISA: true altitude is higher"],"m":["\\Delta h\\approx 4\\times\\frac{h}{1000}\\times\\Delta T_{ISA}"],"id":"c21dd6563","s":"met"},{"t":"met-pressure-altimetry","f":"Transition altitude, transition level and transition layer?","a":"Below the <b>transition altitude</b> use QNH (altitude). Above the <b>transition level</b> use 1013.25 hPa (flight levels).","l":["The transition layer lies between the two","Vertical position: altitude (QNH), height (QFE), flight level (1013)","Set the standard setting when climbing through the transition altitude"],"id":"cf8164315","s":"met"},{"t":"met-pressure-altimetry","f":"What is the difference between QNH and QFF?","a":"<b>QNH</b> is station pressure reduced to mean sea level using ISA temperatures. <b>QFF</b> is reduced using the actual temperature of the air column.","tip":"QFF is used for synoptic charts, QNH for altimeter settings.","id":"c30d057d7","s":"met"},{"t":"met-pressure-altimetry","f":"How do you convert QNH to QFE?","a":"Subtract the elevation expressed in hPa.","l":["QNH 1013 at elevation 900 ft gives QFE ≈ 983 hPa"],"m":["QFE=QNH-\\frac{\\text{elevation (ft)}}{30}"],"id":"cb7595f74","s":"met"},{"t":"met-temperature-humidity-cloud-b","f":"How do you estimate cloud base?","a":"Use the dew-point spread. The temperature falls 3 °C per 1000 ft and the dew point 0.5 °C, so they close 2.5 °C per 1000 ft.","l":["T = 24 °C, Td = 14 °C: spread 10, base ≈ 4000 ft above the surface"],"m":["\\text{Cloud base (ft)}\\approx 400\\times(T-T_d)","\\text{or }\\ 122\\times(T-T_d)\\ \\text{m}"],"d":"cbase","id":"c1522d672","s":"met"},{"t":"met-temperature-humidity-cloud-b","f":"What are dew point and relative humidity?","a":"<b>Dew point</b> is the temperature at which the air becomes saturated. <b>Relative humidity</b> is the vapour present as a percentage of the most the air could hold at that temperature.","l":["When T = Td, RH is 100 % (saturation)","Cooling raises RH; warming lowers it","Warm air can hold more vapour than cold air"],"id":"ca6795c53","s":"met"},{"t":"met-temperature-humidity-cloud-b","f":"What is an inversion and where do you see them?","a":"A layer where temperature <b>increases</b> with height.","l":["Radiation inversion: clear calm night, near the ground","Advection, subsidence (in anticyclones) and frontal inversions","Very stable: traps smoke, haze and low cloud, and can cause fog"],"id":"c24cb3283","s":"met"},{"t":"met-temperature-humidity-cloud-b","f":"When is the temperature at its daily extremes?","a":"Maximum about 1–2 hours after local noon. Minimum around sunrise.","l":["Cloud cover and wind reduce the daily range","Dry air and clear skies increase it"],"id":"c88bcf6ab","s":"met"},{"t":"met-temperature-humidity-cloud-b","f":"Four ways heat moves in the atmosphere?","a":"Radiation, conduction, convection (vertical) and advection (horizontal), plus latent heat from phase changes.","tip":"The atmosphere is warmed mostly from below by the Earth’s surface, not directly by the Sun.","id":"cbd1147cb","s":"met"},{"t":"met-stability-adiabatics","f":"DALR, SALR and ELR: what are the values?","a":"<b>DALR</b> 3 °C per 1000 ft (9.8 °C/km). <b>SALR</b> about 1.5 °C per 1000 ft (varies). <b>ELR</b> averages 2 °C per 1000 ft.","l":["A rising parcel cools at DALR until saturated, then at the SALR","The SALR is smaller because condensation releases latent heat"],"d":"lapse","id":"cfdd4399a","s":"met"},{"t":"met-stability-adiabatics","f":"Stable, unstable or conditionally unstable?","a":"Compare the environmental lapse rate (ELR) with the parcel’s:","l":["<b>Absolutely stable</b>: ELR < SALR","<b>Conditionally unstable</b>: SALR < ELR < DALR","<b>Absolutely unstable</b>: ELR > DALR"],"tip":"Dry parcel colder than its surroundings sinks back. Warmer than its surroundings, it keeps rising.","id":"c26017ff6","s":"met"},{"t":"met-stability-adiabatics","f":"What weather goes with stable and unstable air?","a":"<b>Stable</b>: layer cloud (St, As, Ns), fog, poor visibility, smooth air. <b>Unstable</b>: heap cloud (Cu, Cb), showers, good visibility, turbulence.","id":"c6484ca46","s":"met"},{"t":"met-stability-adiabatics","f":"What is the foehn effect?","a":"Air rises on the windward side, cools at DALR then SALR (rain falls). It descends on the lee side warming at the DALR, so it arrives <b>warmer and drier</b>.","l":["Example: 20 °C air rises 6000 ft with cloud base at 2000 ft. Dry ascent: −6 °C. Saturated ascent (4000 ft): −6 °C. Top: 8 °C.","Descending 6000 ft at the DALR adds 18 °C, so it reaches 26 °C on the lee side."],"id":"c1ebaf1e3","s":"met"},{"t":"met-pressure-systems-depressions","f":"Highs and lows: what is the weather and circulation?","a":"<b>Low</b>: air converges and rises, cloud and rain, anticlockwise in the northern hemisphere. <b>High</b>: air sinks and diverges, clear skies, clockwise.","l":["Reverse the circulation directions in the southern hemisphere","Col: saddle between two highs and two lows, light winds, fog or thunderstorms","Ridge and trough: extensions of high and low pressure"],"d":"geo","id":"c5f1e5dff","s":"met"},{"t":"met-pressure-systems-depressions","f":"How does a frontal depression develop?","a":"A wave forms on the polar front, deepens, and the faster cold front overtakes the warm front to make an <b>occlusion</b>.","l":["Warm sector between the two fronts","Cold front moves faster than the warm front","The system then fills and decays"],"id":"c68c5dff4","s":"met"},{"t":"met-winds-upper-winds","f":"What is the geostrophic wind and when does it apply?","a":"The wind balanced between the pressure gradient force and the Coriolis force, blowing parallel to straight isobars.","l":["Closer isobars: stronger wind","Speed is inversely proportional to sin latitude and density","Not valid near the equator (within about 15°)"],"m":["V_g=\\frac{1}{2\\Omega\\rho\\sin\\phi}\\,\\frac{\\Delta p}{\\Delta n}"],"d":"geo","id":"c888019c0","s":"met"},{"t":"met-winds-upper-winds","f":"Buys Ballot’s law?","a":"In the northern hemisphere, stand with your back to the wind: low pressure is on your <b>left</b>.","tip":"Opposite in the southern hemisphere.","id":"c3c4d41b0","s":"met"},{"t":"met-winds-upper-winds","f":"What does friction do to the surface wind?","a":"It slows the wind and <b>backs</b> it (northern hemisphere) relative to the geostrophic wind.","l":["Over land: about 30° backing, speed 40–50 % of geostrophic","Over sea: about 10–15° backing, speed about 70 %","Winds veer with height up to the gradient level (about 2000 ft)"],"id":"cb0b9a3a3","s":"met"},{"t":"met-winds-upper-winds","f":"Gradient wind versus geostrophic?","a":"Gradient wind includes the effect of curved isobars.","l":["Around a low: gradient wind is <b>weaker</b> than geostrophic (sub-geostrophic)","Around a high: <b>stronger</b> (super-geostrophic)"],"id":"c30a6b8dc","s":"met"},{"t":"met-winds-upper-winds","f":"What is the thermal wind?","a":"The change in geostrophic wind with height caused by a horizontal temperature gradient.","l":["It blows parallel to the isotherms with the cold air on the left (northern hemisphere)","Explains why westerlies strengthen with height in mid-latitudes"],"id":"c99ba3db1","s":"met"},{"t":"met-winds-upper-winds","f":"Sea breeze and land breeze?","a":"<b>Sea breeze</b>: by day, from sea to land (land heats faster). <b>Land breeze</b>: at night, from land to sea.","l":["Sea breeze is stronger and may reach 10–15 kt in the afternoon","Anabatic wind blows up a sunny slope, katabatic wind flows down a cold slope at night"],"id":"c5f89fd42","s":"met"},{"t":"met-jet-streams","f":"What is a jet stream?","a":"A narrow, fast ribbon of wind of at least <b>60 kt</b>, usually near the tropopause.","l":["Polar-front jet: 30 000–35 000 ft, 40–60°, strongest in winter","Subtropical jet: about 40 000 ft near 30°","Tropical easterly jet: over India in the monsoon (about 15°N)","Wind speeds are 100–200 kt at the core"],"d":"jet","id":"c09a1be81","s":"met"},{"t":"met-jet-streams","f":"Where is clear-air turbulence worst around a jet stream?","a":"Where the wind shear is strongest: on the <b>cold (polar) side</b>, below and above the core, and near the tropopause break.","l":["Avoid by a change of level (1000–2000 ft is often enough)","CAT is invisible: use SIGWX charts and PIREPs"],"id":"ce1495a2c","s":"met"},{"t":"met-jet-streams","f":"The subtropical westerly jet over India?","a":"In winter it lies over north India, bringing western disturbances; it shifts north of the Himalaya before the monsoon sets in.","tip":"Winter: subtropical westerly jet. Summer: tropical easterly jet.","id":"c5ae08649","s":"met"},{"t":"met-clouds-fog-precipitation","f":"Cloud types by level?","a":"Three levels (temperate regions):","l":["<b>High</b> (above 16 500 ft): Ci, Cc, Cs","<b>Medium</b> (6500–23 000 ft): Ac, As, Ns","<b>Low</b> (below 6500 ft): St, Sc, Cu, Cb bases"],"d":"clouds","id":"c94ecb6f8","s":"met"},{"t":"met-clouds-fog-precipitation","f":"How is cloud amount reported?","a":"In oktas (eighths of the sky):","l":["<b>FEW</b> 1–2 oktas","<b>SCT</b> 3–4 oktas","<b>BKN</b> 5–7 oktas","<b>OVC</b> 8 oktas","Ceiling is the lowest layer of BKN or OVC"],"id":"c1fc727c8","s":"met"},{"t":"met-clouds-fog-precipitation","f":"Types of fog and how they form?","a":"Fog is visibility below 1000 m.","l":["<b>Radiation fog</b>: clear, calm night, moist air, ground cools","<b>Advection fog</b>: warm moist air over a cold surface, wind 5–15 kt","<b>Steam fog</b>: cold air over warmer water","<b>Upslope fog</b>: moist air forced up a slope","<b>Frontal fog</b>: rain falls into cold air"],"tip":"Mist is 1000 to 5000 m; haze is dry particles.","id":"cd25855e5","s":"met"},{"t":"met-clouds-fog-precipitation","f":"Precipitation: which cloud gives what?","a":"Match cloud to precipitation:","l":["Drizzle: St","Continuous rain: Ns, As","Showers, hail: Cu, Cb","Snow: Ns and Cb in cold air","Freezing rain: rain falling through a sub-zero layer (severe icing)"],"id":"c4516ddd4","s":"met"},{"t":"met-clouds-fog-precipitation","f":"Five ways clouds form?","a":"Convection, orographic lift, frontal lift, turbulent mixing and radiative cooling (fog).","tip":"Each lifts or cools air until it reaches its dew point.","id":"c0d842888","s":"met"},{"t":"met-fronts-air-masses","f":"What is a cold front like?","a":"Steep slope (about 1 : 50), moves fast, lifts warm air sharply.","l":["Cb, heavy showers, squalls, thunderstorms","Pressure rises, temperature drops, wind veers (northern hemisphere)","Visibility poor in rain, then excellent"],"d":"coldfront","id":"c7f0deb59","s":"met"},{"t":"met-fronts-air-masses","f":"What is a warm front like?","a":"Gentle slope (about 1 : 150), warm air rises over cold air.","l":["Cloud sequence Ci, Cs, As, Ns","Steady rain, low cloud, poor visibility ahead of the front","Pressure falls ahead, steadies behind; wind veers; temperature rises behind"],"d":"warmfront","id":"c2f8800c4","s":"met"},{"t":"met-fronts-air-masses","f":"What is an occlusion?","a":"Where the cold front catches up with the warm front and lifts the warm sector off the ground.","l":["<b>Cold occlusion</b>: air behind is colder than the air ahead","<b>Warm occlusion</b>: air behind is warmer than the air ahead","Weather combines both fronts"],"id":"cac08bb64","s":"met"},{"t":"met-fronts-air-masses","f":"Air mass names?","a":"Named by source region and surface: <b>m</b> maritime, <b>c</b> continental; <b>T</b> tropical, <b>P</b> polar, <b>A</b> arctic.","l":["mT: warm and moist, fog and low cloud","cP: cold and dry, good visibility","Modification occurs as the mass moves away from its source"],"id":"c05580275","s":"met"},{"t":"met-thunderstorms-turbulence-win","f":"What are the three stages of a thunderstorm?","a":"Cumulus, mature, dissipating.","l":["<b>Cumulus</b>: updrafts only","<b>Mature</b>: updrafts and downdrafts, rain, lightning, anvil forms","<b>Dissipating</b>: downdrafts dominate and the cell dies"],"d":"tstorm","tip":"It needs unstable air, moisture and a trigger to lift.","id":"ca1333df1","s":"met"},{"t":"met-thunderstorms-turbulence-win","f":"Thunderstorm hazards and avoidance?","a":"Severe turbulence, hail, lightning, icing, windshear, microbursts, heavy rain and tornadoes.","l":["Never fly under the anvil","Stay at least 10 NM from a Cb (20 NM if severe)","Don’t try to fly through, over or under"],"id":"ceed29b52","s":"met"},{"t":"met-thunderstorms-turbulence-win","f":"What is a microburst?","a":"A small, intense downdraft from a Cb that spreads out at the ground.","l":["Encounter order: headwind gain, downdraft, tailwind loss","Lasts only minutes, dangerous at take-off and landing","If a warning is given, go around"],"d":"micro","id":"cbcf624dc","s":"met"},{"t":"met-thunderstorms-turbulence-win","f":"Types of turbulence?","a":"Convective, mechanical, clear-air (CAT), mountain wave and wake.","l":["Mechanical: wind over obstacles, rough low-level air","Mountain wave: lenticular clouds, rotor below","CAT: near jet streams, no cloud warning"],"id":"cdd7c6772","s":"met"},{"t":"met-thunderstorms-turbulence-win","f":"Wind shear: what is it?","a":"A change in wind speed or direction over a short distance, horizontally or vertically.","l":["Greatest hazards: microbursts, fronts, inversions, low-level jets","Reduce speed fluctuation by flying the approach carefully and using the correct additive"],"id":"c5f662392","s":"met"},{"t":"met-icing","f":"When does airframe icing form?","a":"In visible moisture (cloud or rain) with temperatures at or below freezing and supercooled water droplets.","l":["Worst between 0 and −10 °C","Freezing rain is the most severe","Ice adds weight, drag and stall speed, and reduces lift"],"id":"cc7bc254f","s":"met"},{"t":"met-icing","f":"Clear, rime and mixed ice?","a":"Differ by droplet size and temperature:","l":["<b>Clear</b> (glaze): large drops, 0 to −10 °C, hard, transparent, dangerous","<b>Rime</b>: small drops, below about −10 °C, white and brittle","<b>Mixed</b>: both, in between"],"id":"cef0bd035","s":"met"},{"t":"met-icing","f":"What is carburettor icing?","a":"Ice in the carburettor throat from fuel evaporation and the pressure drop, which can cool the air by 20 °C or more.","l":["Can form with outside temperatures well above freezing, in humid air","Carb heat on to clear it, and as a precaution when descending"],"id":"cffb751c1","s":"met"},{"t":"met-icing","f":"Hoar frost and rain ice?","a":"<b>Hoar frost</b>: white ice crystals on a surface below 0 °C by direct deposition from the air. It must be removed before take-off.","tip":"Freezing rain under a warm front is the worst icing environment.","id":"c9043c1e0","s":"met"},{"t":"met-tropical-cyclones","f":"What does a tropical cyclone need?","a":"Sea surface temperature at least about 26.5 °C, latitude beyond about 5°, high humidity and low wind shear.","l":["Intense low with an eye of light wind and clear sky","Eyewall: the strongest winds and heaviest rain","Anticlockwise in the northern hemisphere"],"d":"tropcy","id":"cc72c6f95","s":"met"},{"t":"met-tropical-cyclones","f":"Names of tropical cyclones?","a":"The name depends on the ocean:","l":["Atlantic and north-east Pacific: hurricane","North-west Pacific: typhoon","Indian Ocean and South Pacific: cyclone"],"id":"c9bb263d1","s":"met"},{"t":"met-tropical-cyclones","f":"How does IMD classify cyclones by wind?","a":"By maximum sustained wind (North Indian Ocean):","l":["Depression 17–27 kt","Deep depression 28–33 kt","Cyclonic storm 34–47 kt","Severe cyclonic storm 48–63 kt","Very severe 64–89 kt · Extremely severe 90–119 kt · Super cyclonic 120 kt or more"],"id":"c10c029f1","s":"met"},{"t":"met-tropical-cyclones","f":"The dangerous semicircle?","a":"In the northern hemisphere it is the <b>right-hand semicircle</b> relative to the storm’s motion, where the wind adds to the storm’s forward speed.","id":"c169db3e6","s":"met"},{"t":"met-climatology-monsoon","f":"How does the south-west monsoon work over India?","a":"Strong summer heating over north-west India creates a heat low. Moist cross-equatorial air is drawn in.","l":["Onset over Kerala about 1 June; covers India by about 15 July","Withdrawal begins from north-west India in September","Tropical easterly jet and the Tibetan high help drive it"],"id":"c3a09b0d8","s":"met"},{"t":"met-climatology-monsoon","f":"What are western disturbances?","a":"Winter systems from the Mediterranean region that bring rain and snow to north India, carried by the subtropical westerly jet.","tip":"Roughly December to March.","id":"c980d74b5","s":"met"},{"t":"met-climatology-monsoon","f":"What are nor’westers?","a":"Violent pre-monsoon thunderstorms with squalls, hail and heavy rain over Bengal, Bihar and Assam (March to May). Known locally as Kalbaisakhi.","id":"c65fe68a9","s":"met"},{"t":"met-climatology-monsoon","f":"Four seasons of India (IMD)?","a":"Winter (Dec–Feb), pre-monsoon (Mar–May), south-west monsoon (Jun–Sep), post-monsoon (Oct–Nov).","l":["The north-east monsoon brings rain to Tamil Nadu from October to December","“Loo”: hot dry westerly wind over north India in April to June"],"id":"cc2b7cc61","s":"met"},{"t":"met-weather-reports-charts","f":"How do you read a METAR?","a":"Groups in order: station, time, wind, visibility, weather, cloud, temperature and dew point, pressure, trend.","l":["<b>VABB 071530Z</b> station, day 07, 1530 UTC","<b>27012G22KT</b> wind 270° 12 kt gusting 22","<b>3000 −RA BR</b> vis 3000 m, light rain, mist","<b>SCT008 BKN015</b> cloud base 800 and 1500 ft","<b>24/23 Q1008</b> temperature 24, dew point 23, QNH 1008 hPa"],"tip":"Cloud heights are above aerodrome level, in hundreds of feet.","id":"c497d414b","s":"met"},{"t":"met-weather-reports-charts","f":"What is TAF?","a":"A forecast for an aerodrome, valid 6 to 30 hours (commonly 9, 24 or 30).","l":["<b>BECMG</b>: gradual change","<b>TEMPO</b>: temporary fluctuations, each under 1 hour and covering less than half the period","<b>PROB30 / PROB40</b>: probability","<b>FM</b>: rapid change from a time","<b>CAVOK</b>: visibility ≥ 10 km, no cloud below 5000 ft, no significant weather"],"id":"cc746fff6","s":"met"},{"t":"met-weather-reports-charts","f":"Weather codes you must know?","a":"Intensity and descriptor with phenomenon:","l":["− light, + heavy; VC in the vicinity","RA rain, SN snow, DZ drizzle, GR hail","TS thunderstorm, SH showers, FZ freezing","FG fog, BR mist, HZ haze, FU smoke","DS dust storm, SS sandstorm, FC funnel cloud"],"id":"c0c5fe008","s":"met"},{"t":"met-weather-reports-charts","f":"SIGMET, AIRMET, SPECI, VOLMET?","a":"Different warnings and reports:","l":["<b>SIGMET</b>: hazard warnings for aircraft, valid up to 4 h (6 h for volcanic ash and tropical cyclone)","<b>AIRMET</b>: lower-level hazards for light aircraft","<b>SPECI</b>: special report when significant change occurs","<b>VOLMET</b>: broadcast of METARs for aircraft in flight"],"id":"c760145c7","s":"met"},{"t":"met-meteorological-calculations","f":"How do you calculate density altitude?","a":"Start from pressure altitude and add 120 ft for every °C above ISA.","l":["PA 4000 ft, OAT 25 °C: ISA 7 °C, deviation +18, DA = 4000 + 2160 = 6160 ft"],"m":["DA=PA+120\\,(OAT-T_{ISA})","T_{ISA}\\approx 15-2\\times\\frac{PA}{1000}"],"id":"c4d39e66b","s":"met"},{"t":"met-meteorological-calculations","f":"How do you find temperature at altitude in ISA?","a":"Take off 2 °C per 1000 ft from the surface value.","l":["ISA deviation = actual temperature − ISA temperature"],"m":["T_h=T_0-2\\times\\frac{h}{1000}"],"id":"cb83eca7a","s":"met"},{"t":"met-meteorological-calculations","f":"How do you estimate the freezing level?","a":"Divide the surface temperature by the lapse rate.","l":["Surface 12 °C: freezing level ≈ 6000 ft"],"m":["h_{0^\\circ}\\approx\\frac{T_0}{2}\\times 1000\\ \\text{ft}"],"id":"c4830000c","s":"met"},{"t":"met-meteorological-calculations","f":"True altitude with a temperature correction: how?","a":"Work out the ISA deviation at the level, then multiply.","l":["Indicated 10 000 ft, ISA −15 °C: error −600 ft, true altitude 9400 ft"],"m":["\\text{True alt}\\approx\\text{Indicated}+4\\times\\frac{h}{1000}\\times\\Delta T_{ISA}"],"id":"c26714c63","s":"met"},{"t":"reg-icao-annexes-conventions","f":"What are the ICAO Annexes 1 to 19?","a":"Learn them in order:","l":["1 Personnel Licensing · 2 Rules of the Air · 3 Meteorology","4 Aeronautical Charts · 5 Units of Measurement · 6 Operation of Aircraft","7 Aircraft Nationality and Registration Marks · 8 Airworthiness · 9 Facilitation","10 Aeronautical Telecommunications · 11 Air Traffic Services · 12 Search and Rescue","13 Accident and Incident Investigation · 14 Aerodromes · 15 Aeronautical Information Services","16 Environmental Protection · 17 Security · 18 Dangerous Goods · 19 Safety Management"],"id":"c7a8d1d8d","s":"reg"},{"t":"reg-icao-annexes-conventions","f":"Where was ICAO created and how is it run?","a":"By the Chicago Convention of 1944; ICAO came into being on 4 April 1947 with its headquarters in Montreal.","l":["Assembly: all member states, meets every 3 years","Council: 36 states, the governing body","Air Navigation Commission prepares technical standards","ICAO is a specialised agency of the United Nations"],"id":"cf2d69501","s":"reg"},{"t":"reg-icao-annexes-conventions","f":"Standards, Recommended Practices and PANS?","a":"<b>Standards</b> (“shall”): states must comply or file a difference. <b>Recommended Practices</b> (“should”): states try to comply. <b>PANS</b>: procedures, approved by the Council.","l":["Article 37 adopts the standards; Article 38 allows departures if notified to ICAO","SUPPs are regional procedures"],"id":"cfd8f05da","s":"reg"},{"t":"reg-icao-annexes-conventions","f":"The freedoms of the air?","a":"Rights to operate between states:","l":["1st: fly over a state without landing","2nd: land for technical reasons (no traffic)","3rd: carry traffic from your state to another","4th: carry traffic from another state to yours","5th: carry traffic between two other states on a flight to or from your own","1st and 2nd are in the International Air Services Transit Agreement; the others are bilateral"],"id":"c28a1f4b8","s":"reg"},{"t":"reg-icao-annexes-conventions","f":"Key articles of the Chicago Convention?","a":"Know the topics:","l":["Art. 1: complete and exclusive sovereignty over airspace","Art. 5: non-scheduled flights; Art. 6: scheduled services need permission","Art. 12: rules of the air","Art. 29: documents carried on board","Art. 31 / 32: certificate of airworthiness / licences of crew","Art. 33: recognition of certificates and licences"],"id":"c898cf084","s":"reg"},{"t":"reg-icao-annexes-conventions","f":"Which convention covers what?","a":"Match the place and subject:","l":["<b>Tokyo 1963</b>: offences on board","<b>The Hague 1970</b>: unlawful seizure (hijacking)","<b>Montreal 1971</b>: sabotage against civil aviation","<b>Warsaw 1929 / Montreal 1999</b>: liability to passengers","<b>Rome 1952</b>: damage to third parties on the surface","<b>Cape Town 2001</b>: mobile equipment"],"id":"c2baf0e02","s":"reg"},{"t":"reg-aircraft-act-rules-dgca","f":"Who is who in Indian civil aviation?","a":"Roles of the main bodies:","l":["<b>MoCA</b>: Ministry of Civil Aviation, policy","<b>DGCA</b>: regulator, licences, airworthiness and safety oversight","<b>BCAS</b>: Bureau of Civil Aviation Security","<b>AAI</b>: Airports Authority of India, airports and air traffic services","<b>AAIB</b>: Aircraft Accident Investigation Bureau"],"id":"cbf4f1c49","s":"reg"},{"t":"reg-aircraft-act-rules-dgca","f":"Which laws govern aviation in India?","a":"The <b>Aircraft Act 1934</b> and the <b>Aircraft Rules 1937</b>, with DGCA Civil Aviation Requirements (CARs).","l":["The Bharatiya Vayuyan Adhiniyam 2024 replaces the 1934 Act (reported in force from 1 January 2025)","Question papers still use the older names, so know both","CARs are grouped into sections by subject (airworthiness, operations, licensing and so on)"],"id":"c53507cbc","s":"reg"},{"t":"reg-registration-airworthiness","f":"Documents carried on board (Article 29)?","a":"The standard list for an international flight:","l":["Certificate of registration","Certificate of airworthiness","Crew licences","Journey log book","Aircraft radio station licence","Passenger manifest (names, places of embarkation and destination)","Cargo manifest and declarations"],"id":"c996e066f","s":"reg"},{"t":"reg-registration-airworthiness","f":"How is an Indian aircraft marked?","a":"Nationality mark <b>VT</b> followed by a registration mark of three letters, for example VT-ABC.","l":["Annex 7 sets the nationality, common and registration marks","Certificate of registration shows the owner; it is not proof of ownership by itself"],"id":"c31429d11","s":"reg"},{"t":"reg-registration-airworthiness","f":"What does the certificate of airworthiness say?","a":"The aircraft complies with its type certificate and is safe for flight in the category stated.","l":["Kept valid by an Airworthiness Review Certificate and approved maintenance","Annex 8 covers airworthiness","The aircraft must be maintained and released to service by an approved person"],"id":"ca6eb8bae","s":"reg"},{"t":"reg-licensing-medical","f":"Licence types and minimum ages?","a":"ICAO Annex 1:","l":["PPL: 17 years · CPL: 18 · ATPL: 21","MPL: multi-crew pilot licence","Instrument, type and class ratings","FRTOL: flight radio telephone operator licence"],"id":"c926cd272","s":"reg"},{"t":"reg-licensing-medical","f":"ICAO language proficiency levels?","a":"Six levels: <b>Level 4</b> is the minimum operational standard.","l":["Level 4 valid 4 years · Level 5 valid 6 years · Level 6 does not expire","Applies to radiotelephony in English or the language used by the ground station"],"id":"c8f076572","s":"reg"},{"t":"reg-licensing-medical","f":"Medical certificate classes?","a":"<b>Class 1</b>: CPL, ATPL, MPL. <b>Class 2</b>: PPL. <b>Class 3</b>: air traffic controllers.","l":["Validity depends on class and age; check the current DGCA requirement","Pilots must not exercise licence privileges if their medical fitness has declined"],"id":"c0cf26f6a","s":"reg"},{"t":"reg-licensing-medical","f":"ATPL experience: the ICAO figure?","a":"Not less than <b>1500 hours</b> of flight time, including night and instrument flight, as set in Annex 1.","id":"c57f625b1","s":"reg"},{"t":"reg-rules-of-the-air","f":"Right-of-way rules?","a":"Three basic situations:","l":["<b>Head-on</b>: both turn right","<b>Converging</b>: the aircraft that has the other on its right gives way","<b>Overtaking</b>: the overtaking aircraft keeps clear by altering heading to the right","Landing aircraft: the lower aircraft has priority","Priority order of types: balloons, gliders, airships, powered aircraft"],"d":"giveway","id":"c15265f19","s":"reg"},{"t":"reg-rules-of-the-air","f":"What is the semicircular rule?","a":"Cruising levels depend on magnetic track.","l":["Track 000° to 179°: <b>odd</b> thousands (FL 290, 310, 330…)","Track 180° to 359°: <b>even</b> thousands (FL 300, 320, 340…)","VFR flights add 500 ft (for example FL 35 or 3500 ft)"],"d":"levels","tip":"East is odd, west is even.","id":"c95e4ee63","s":"reg"},{"t":"reg-rules-of-the-air","f":"Minimum heights over the ground?","a":"Except for take-off or landing:","l":["Over congested areas: 300 m (1000 ft) above the highest obstacle within 600 m","Elsewhere: 150 m (500 ft) above ground or water","Never closer than 150 m to any person, vessel, vehicle or structure"],"id":"c89f09236","s":"reg"},{"t":"reg-rules-of-the-air","f":"VFR weather minima (ICAO, Classes B to E)?","a":"Above 3050 m (10 000 ft) AMSL: 8 km visibility. At or below it: 5 km.","l":["Distance from cloud: 1500 m horizontal, 300 m (1000 ft) vertical","Class B airspace: clear of cloud","Check the Indian AIP for the local minima"],"id":"c5cc3a8db","s":"reg"},{"t":"reg-rules-of-the-air","f":"Navigation and anti-collision lights?","a":"Red on the <b>left</b>, green on the <b>right</b>, white at the tail.","l":["Anti-collision lights must be on in flight and whenever the engines run","Landing lights are used below 10 000 ft or in busy airspace as recommended"],"d":{"k":"navl"},"id":"c685ca2b7","s":"reg"},{"t":"reg-rules-of-the-air","f":"Transponder emergency codes?","a":"Set on the SSR code:","l":["<b>7700</b> emergency","<b>7600</b> radio failure","<b>7500</b> unlawful interference (hijack)"],"tip":"7-5, 7-6, 7-7: hijack, radio, emergency (in that order).","id":"c9d265350","s":"reg"},{"t":"reg-rules-of-the-air","f":"Joining an aerodrome traffic circuit?","a":"Standard circuit legs: upwind, crosswind, downwind, base, final.","l":["Standard patterns are left-handed unless the airfield says otherwise","Check wind direction on the sock and give way to aircraft already in the circuit","Join by overhead, straight in or downwind as local rules allow"],"d":"circuit","id":"c88c46c40","s":"reg"},{"t":"reg-air-traffic-services","f":"What does each airspace class provide?","a":"ICAO Annex 11 classes:","l":["<b>A</b>: IFR only, all separated, clearance required","<b>B</b>: IFR and VFR, all separated","<b>C</b>: IFR separated from all; VFR from IFR only","<b>D</b>: IFR from IFR; VFR gets traffic information","<b>E</b>: IFR from IFR; VFR not separated","<b>F</b>: advisory (IFR), information (VFR) · <b>G</b>: flight information only"],"id":"cf8974c8a","s":"reg"},{"t":"reg-air-traffic-services","f":"Speed limits and RVSM?","a":"Below FL 100, 250 kt IAS in Classes C, D, E, F and G.","l":["RVSM: 1000 ft separation between FL 290 and FL 410 for approved aircraft and operators","Outside RVSM above FL 290: 2000 ft"],"id":"ce502ebbc","s":"reg"},{"t":"reg-air-traffic-services","f":"Radar separation minima (ICAO)?","a":"Horizontal: <b>5 NM</b> en route, <b>3 NM</b> where surveillance allows near aerodromes. Vertical: 1000 ft below FL 290.","l":["Wake turbulence by radar: heavy behind heavy 4 NM, medium behind heavy 5 NM, light behind heavy 6 NM, light behind medium 5 NM"],"id":"ca723f6b3","s":"reg"},{"t":"reg-air-traffic-services","f":"How is a holding pattern flown and entered?","a":"Standard pattern: right-hand turns, 1 minute legs up to 14 000 ft (1½ minutes above).","l":["Entries: <b>direct</b>, <b>parallel</b> or <b>teardrop</b>, decided by the 70° line","Turn at Rate 1 (3°/s) or 25° bank, whichever needs the lower bank","Maximum speeds: 230 kt to 14 000 ft, 240 kt to 20 000 ft, 265 kt to 34 000 ft, Mach 0.83 above"],"d":{"raw":"holdentry"},"id":"c1c597f0d","s":"reg"},{"t":"reg-air-traffic-services","f":"Primary and secondary radar?","a":"<b>Primary</b> radar listens for the pulse bounced off the aircraft. <b>Secondary</b> radar asks a transponder to reply.","l":["SSR interrogates on 1030 MHz and replies on 1090 MHz","Mode A: identity code (4096 codes) · Mode C: pressure altitude · Mode S: selective addressing, enables ADS-B and TCAS","PSR needs no cooperation, so it sees non-transponder aircraft and weather"],"m":["R=\\frac{c\\,\\Delta t}{2}"],"d":"psrssr","id":"cb8c00c22","s":"reg"},{"t":"reg-air-traffic-services","f":"Radiotelephony words you must use right?","a":"Standard phraseology:","l":["<b>Roger</b>: received your last transmission","<b>Wilco</b>: will comply","<b>Affirm</b> / <b>Negative</b>: yes / no","<b>Say again</b>: repeat; never “repeat”","<b>Standby</b>: wait; I will call you","<b>Readback</b> required for clearances and runway instructions","Readability scale 1 (unreadable) to 5 (perfectly readable)"],"id":"cf2ca95b9","s":"reg"},{"t":"reg-air-traffic-services","f":"FIRs in India?","a":"Four flight information regions: <b>Delhi</b> (VIDF), <b>Mumbai</b> (VABF), <b>Kolkata</b> (VECF) and <b>Chennai</b> (VOMF).","tip":"The ICAO prefix for India is VA, VE, VI and VO.","id":"c0f951a65","s":"reg"},{"t":"reg-aerodromes-lighting-marking","f":"Runway markings: what are they?","a":"From the threshold inwards:","l":["Threshold stripes, then the runway designator (heading ÷ 10, nearest ten)","Touchdown zone bars in pairs","Aiming point: two large bars","Centreline dashes, white edge lines"],"d":"rwymark","id":"c81521691","s":"reg"},{"t":"reg-aerodromes-lighting-marking","f":"Runway lighting colours?","a":"What you see on an instrument runway:","l":["Edge: white (yellow on the last 600 m or half the length)","Threshold: green · Runway end: red","Centreline: white, alternating red/white then all red near the end","Touchdown zone: white · Taxiway centreline: green · Taxiway edge: blue"],"id":"cac082778","s":"reg"},{"t":"reg-aerodromes-lighting-marking","f":"How do you read PAPI?","a":"Four lights set on one side of the runway: more white means high, more red means low.","l":["2 white, 2 red: on the glide path (usually 3°)","3 white, 1 red: slightly high","1 white, 3 red: slightly low","All white / all red: too high / too low"],"d":"papi","id":"c3175080c","s":"reg"},{"t":"reg-aerodromes-lighting-marking","f":"Declared distances of a runway?","a":"TORA, TODA, ASDA and LDA.","l":["TORA: take-off run available","TODA = TORA + clearway (clearway ≤ half TORA)","ASDA = TORA + stopway","LDA: landing distance available"],"tip":"RESA minimum 90 m, recommended 240 m.","id":"c65b45877","s":"reg"},{"t":"reg-aerodromes-lighting-marking","f":"Aerodrome beacons?","a":"A land aerodrome beacon flashes <b>alternate white and green</b>. A water aerodrome beacon flashes alternate white and yellow.","l":["Identification beacon: green flashing morse (land), yellow (water)","Seen by day in poor visibility, at night as a primary guide"],"id":"c78459b4b","s":"reg"},{"t":"reg-aerodromes-lighting-marking","f":"Rescue and fire fighting categories?","a":"Based on the longest aeroplane using the aerodrome (overall length):","l":["Cat 1 under 9 m · 2 up to 12 m · 3 up to 18 m · 4 up to 24 m","Cat 5 up to 28 m · 6 up to 39 m · 7 up to 49 m","Cat 8 up to 61 m · 9 up to 76 m · 10 up to 90 m"],"id":"cd08e795e","s":"reg"},{"t":"reg-aerodromes-lighting-marking","f":"Light signals from the tower?","a":"To an aircraft in flight and on the ground:","l":["<b>Steady green</b>: cleared to land / cleared for take-off","<b>Steady red</b>: give way and continue circling / stop","<b>Flashing green</b>: return for landing / cleared to taxi","<b>Flashing red</b>: aerodrome unsafe, do not land / taxi clear of the runway","<b>Flashing white</b>: land and proceed to the apron / return to the starting point"],"id":"c63a211a6","s":"reg"},{"t":"reg-distress-emergency-communica","f":"MAYDAY, PAN PAN and the three phases?","a":"<b>MAYDAY</b>: grave and imminent danger needing help now. <b>PAN PAN</b>: urgency, safety concern but not immediate danger.","l":["Each said three times","Phases: <b>INCERFA</b> (uncertainty), <b>ALERFA</b> (alert), <b>DETRESFA</b> (distress)","Distress message: call sign, nature, intentions, position, level, people on board"],"id":"c298a518d","s":"reg"},{"t":"reg-distress-emergency-communica","f":"Frequencies and beacons for emergencies?","a":"Know the numbers:","l":["<b>121.5 MHz</b>: international VHF emergency","<b>243 MHz</b>: military UHF emergency","<b>406 MHz</b> ELT (with 121.5 homing)","Underwater locating beacon: 37.5 kHz"],"id":"cb7d3de38","s":"reg"},{"t":"reg-distress-emergency-communica","f":"Ground-to-air visual signals?","a":"Symbols laid on the ground:","l":["<b>V</b>: require assistance","<b>X</b>: require medical assistance","<b>N</b>: no / negative","<b>Y</b>: yes / affirmative","<b>→</b>: proceeding in this direction"],"id":"cad6984ef","s":"reg"},{"t":"reg-distress-emergency-communica","f":"Lost radio contact: what do you do?","a":"Squawk <b>7600</b> and follow the failure procedure.","l":["VMC: continue in VMC and land at the nearest suitable aerodrome","IMC: maintain last level and speed (or minimum altitude if higher), then follow the flight plan","Transmit blind and listen on the guard frequency"],"id":"c08158559","s":"reg"},{"t":"reg-accidents-incidents-security","f":"Accident, serious incident, incident?","a":"Annex 13 definitions:","l":["<b>Accident</b>: occurrence in operation with a fatal or serious injury, substantial damage, or the aircraft missing","<b>Serious incident</b>: an incident with a high probability of an accident","<b>Incident</b>: other occurrence affecting safe operation"],"id":"cfb65d23b","s":"reg"},{"t":"reg-accidents-incidents-security","f":"Who investigates and how long does it take?","a":"The State of Occurrence is responsible (in India the AAIB).","l":["Final report is released within 12 months, or an interim statement on each anniversary","Evidence must be preserved; do not move the wreckage except to rescue or protect people","Investigation seeks cause, not blame"],"id":"c26fdf27a","s":"reg"},{"t":"reg-accidents-incidents-security","f":"Flight recorders: how much do they keep?","a":"FDR records at least <b>25 hours</b>; CVR records the last <b>2 hours</b>.","l":["Both are orange so that they are easy to find","Underwater locator beacon at 37.5 kHz"],"id":"cb8b1f7cb","s":"reg"},{"t":"reg-accidents-incidents-security","f":"Dangerous goods classes?","a":"Nine UN classes:","l":["1 Explosives · 2 Gases · 3 Flammable liquids","4 Flammable solids · 5 Oxidisers · 6 Toxic and infectious","7 Radioactive · 8 Corrosives · 9 Miscellaneous"],"id":"c8b1c4f6a","s":"reg"},{"t":"reg-operations-crew-public-healt","f":"Precision approach categories?","a":"By decision height (DH) and runway visual range (RVR):","l":["<b>Cat I</b>: DH ≥ 200 ft, RVR ≥ 550 m","<b>Cat II</b>: DH 100–200 ft, RVR ≥ 300 m","<b>Cat IIIA</b>: DH below 100 ft, RVR ≥ 175 m","<b>Cat IIIB</b>: DH below 50 ft, RVR 50–175 m","<b>Cat IIIC</b>: no DH, no RVR limit"],"id":"caeeca226","s":"reg"},{"t":"reg-operations-crew-public-healt","f":"What does Annex 9 cover?","a":"Facilitation: smooth clearance of aircraft, crews, passengers, baggage and cargo at borders.","l":["Customs, immigration, health and quarantine formalities","Standard documents such as the General Declaration"],"id":"cfd25fef1","s":"reg"},{"t":"reg-operations-crew-public-healt","f":"Flight and duty time limits?","a":"Set in the DGCA CARs (Section 7). They limit flight time, duty periods and set minimum rest.","tip":"Memorise the current CAR numbers, because they change.","id":"c4234e12c","s":"reg"},{"t":"reg-human-performance-limitation","f":"Types of hypoxia?","a":"Not enough oxygen reaching the tissues:","l":["<b>Hypoxic</b>: low partial pressure of oxygen (altitude)","<b>Stagnant</b>: poor circulation (g-forces, cold)","<b>Anaemic</b>: blood cannot carry oxygen (carbon monoxide, anaemia)","<b>Histotoxic</b>: cells cannot use oxygen (alcohol, drugs)"],"id":"c5f1acf87","s":"reg"},{"t":"reg-human-performance-limitation","f":"Time of useful consciousness?","a":"The time you can act sensibly after losing oxygen supply:","l":["FL 180: 20–30 min · FL 220: about 10 min","FL 250: 3–5 min · FL 280: 2.5–3 min","FL 300: 1–2 min · FL 350: 30–60 s","FL 400: 15–20 s · FL 430 and above: 9–12 s"],"tip":"Cabin altitude, not flight level, in a pressurised aircraft.","id":"c86c59bf8","s":"reg"},{"t":"reg-human-performance-limitation","f":"Hyperventilation and carbon monoxide?","a":"<b>Hyperventilation</b>: over-breathing lowers CO₂, causing tingling, dizziness. Breathe slowly or into a bag. <b>CO poisoning</b>: haemoglobin binds CO about 200 times more strongly than oxygen.","l":["CO sources: exhaust and heater leaks, smokers","Treat with 100 % oxygen and fresh air"],"id":"cb493bc40","s":"reg"},{"t":"reg-human-performance-limitation","f":"Decompression sickness and diving?","a":"Nitrogen bubbles form when ambient pressure falls fast.","l":["Wait <b>12 h</b> after a no-decompression dive before flying (up to 8000 ft cabin altitude)","Wait <b>24 h</b> after a decompression dive or before flying above 8000 ft","Symptoms: joint pain (the bends), chokes, rash"],"id":"c1b5fbc02","s":"reg"},{"t":"reg-human-performance-limitation","f":"The eye: rods and cones?","a":"<b>Cones</b> (fovea): colour and detail, daylight. <b>Rods</b> (periphery): dim light, no colour.","l":["Dark adaptation takes 30–45 minutes","At night look slightly off-centre to use the rods","The blind spot is where the optic nerve leaves the eye"],"id":"cf7a1c0c2","s":"reg"},{"t":"reg-human-performance-limitation","f":"Spatial disorientation illusions?","a":"The inner ear misleads you without visual references:","l":["<b>Leans</b>: after a slow roll, a correction feels like banking","<b>Graveyard spiral</b>: unnoticed spiral with rising speed","<b>Somatogravic</b>: acceleration feels like pitching up","<b>Black hole</b>: approach over unlit terrain looks too high","<b>Autokinesis</b>: a static light seems to move"],"tip":"Trust your instruments over your senses.","id":"c20059363","s":"reg"},{"t":"reg-human-performance-limitation","f":"Human factors models?","a":"Reason’s <b>Swiss cheese</b> model: accidents occur when holes in many defences line up. The <b>SHELL</b> model: Software, Hardware, Environment, Liveware (central), Liveware (others).","l":["TEM: threats, errors and undesired states","Yerkes–Dodson: performance peaks at moderate arousal, drops with too little or too much","Cabin altitude in pressurised flight is kept at or below 8000 ft"],"id":"c3c46085d","s":"reg"},{"t":"reg-charges-documents-other","f":"What are the AIS publications?","a":"Annex 15 covers aeronautical information:","l":["<b>AIP</b>: permanent information","<b>AIP supplement</b>: temporary long changes","<b>NOTAM</b>: urgent changes (new N, replace R, cancel C)","<b>AIC</b>: advisory circulars","<b>AIRAC</b>: changes on a 28-day cycle"],"id":"cd8456823","s":"reg"},{"t":"reg-charges-documents-other","f":"Units to use in aviation (Annex 5)?","a":"SI is the base, with permitted non-SI units for aviation:","l":["Altitude and height: feet","Distance: nautical miles","Speed: knots","Vertical speed: feet per minute","Time: UTC"],"id":"c7547b4e1","s":"reg"},{"t":"tec-aerodynamics-performance","f":"Forces in steady level flight?","a":"Lift balances weight; thrust balances drag.","l":["Lift increases with density, speed squared, wing area and lift coefficient","Same form for drag with C<sub>D</sub>"],"m":["L=\\tfrac12\\rho V^2 S C_L","D=\\tfrac12\\rho V^2 S C_D"],"d":"forces","id":"c25871d6b","s":"tec"},{"t":"tec-aerodynamics-performance","f":"What causes a stall?","a":"The wing exceeds its <b>critical angle of attack</b> (about 15–16°) and the airflow separates.","l":["A stall depends on angle of attack, not on speed","Stall speed rises with weight, load factor, forward CG and flap retraction","Recovery: reduce angle of attack first"],"d":"clalpha","id":"c6aecc5a3","s":"tec"},{"t":"tec-aerodynamics-performance","f":"Parasite drag and induced drag: how do they vary?","a":"Parasite drag grows with the square of speed. Induced drag falls with the square of speed.","l":["Total drag is lowest at VMD, where the two are equal","High aspect ratio reduces induced drag"],"m":["C_{D_i}=\\frac{C_L^2}{\\pi\\,e\\,AR}","AR=\\frac{b^2}{S}"],"d":"dragcurve","id":"c38d369d5","s":"tec"},{"t":"tec-aerodynamics-performance","f":"What happens in a level turn?","a":"Lift must increase, so load factor rises with bank angle.","l":["60° bank: n = 2, stall speed up by 41 %","Rate 1 turn: 3° per second, bank ≈ TAS/10 + 7°"],"m":["n=\\frac{1}{\\cos\\phi}","V_{S,\\text{turn}}=V_S\\sqrt n"],"d":{"k":"lf","b":60},"id":"c8b7eaffb","s":"tec"},{"t":"tec-aerodynamics-performance","f":"Turn rate and radius formulas?","a":"Both depend on speed and bank angle.","l":["Higher speed: larger radius, lower rate","Steeper bank: smaller radius, higher rate"],"m":["\\text{Rate}(^\\circ/\\text{s})\\approx\\frac{1091\\tan\\phi}{V(\\text{kt})}","r=\\frac{V^2}{g\\tan\\phi}"],"id":"c103df1c7","s":"tec"},{"t":"tec-aerodynamics-performance","f":"What is ground effect?","a":"Within about one wingspan of the ground the downwash is restricted. Induced drag falls and lift rises.","l":["The aircraft floats on landing, and may lift off below its normal flying speed on take-off","Less induced drag, so less power is needed to hold level flight close to the ground"],"id":"cd3e40ccd","s":"tec"},{"t":"tec-aerodynamics-performance","f":"High-lift devices?","a":"Trailing edge <b>flaps</b> raise CL max and drag; leading edge <b>slats</b> delay the stall to a higher angle of attack.","l":["Plain, split, slotted and Fowler flaps","Krueger flaps on the leading edge","Lower stall speed, shorter take-off and landing runs"],"id":"cb05717ea","s":"tec"},{"t":"tec-aerodynamics-performance","f":"Effects of wing sweep?","a":"Sweepback raises the critical Mach number.","l":["Lower CL max","Tip stall and pitch-up tendency","Dutch roll: needs a yaw damper"],"id":"c054ab131","s":"tec"},{"t":"tec-aerodynamics-performance","f":"Wing-tip vortices and wake turbulence?","a":"Vortices are strongest behind heavy, slow, clean aircraft.","l":["They sink and drift with the wind, and stay on the ground in a calm","Stay above the preceding aircraft’s flight path on approach; land after its touchdown point","Winglets reduce induced drag"],"id":"ce3050a22","s":"tec"},{"t":"tec-aerodynamics-performance","f":"Range and endurance: where are the speeds?","a":"Related to drag and power curves.","l":["Glide ratio = L/D = distance ÷ height, best at VMD","Propeller: max endurance at minimum power speed, max range at VMD","Jet: max endurance at VMD, max range at about 1.32 × VMD","Weight reduces as fuel burns, so speeds fall"],"m":["\\text{glide ratio}=\\frac{L}{D}=\\frac{\\text{distance}}{\\text{height}}"],"id":"c61a41a45","s":"tec"},{"t":"tec-flight-controls-stability","f":"Three axes and their controls?","a":"Roll (longitudinal axis): ailerons. Pitch (lateral axis): elevator. Yaw (vertical axis): rudder.","l":["Adverse yaw: the down-going wing has more drag; fixed by differential or Frise ailerons","Spoilers also help roll and add drag"],"id":"c8b1612a8","s":"tec"},{"t":"tec-flight-controls-stability","f":"What makes an aircraft stable?","a":"Static stability: it returns toward the original attitude. Dynamic stability: the oscillation dies away.","l":["Longitudinal stability needs the CG ahead of the neutral point","Dihedral and sweepback give roll stability","Fin gives directional stability"],"id":"ceeb2e34d","s":"tec"},{"t":"tec-flight-controls-stability","f":"Trim tabs and balance tabs?","a":"<b>Trim tab</b>: relieves control force so the pilot can fly hands-off. <b>Balance (anti-balance) tab</b>: helps move or stabilises the surface.","l":["Servo tabs move the main surface by aerodynamic force","Stabilator: whole tailplane moves, anti-servo tab adds feel"],"id":"c0bf4d6b5","s":"tec"},{"t":"tec-airframe-structures","f":"Types of airframe structure?","a":"Monocoque, semi-monocoque (skin, stringers, frames) and truss.","l":["Most airliners: semi-monocoque, stressed skin","Fail-safe: loss of one part does not cause failure","Fatigue: cracks grow under repeated loads"],"id":"cbb2b8dfb","s":"tec"},{"t":"tec-airframe-structures","f":"Limit load and ultimate load?","a":"<b>Ultimate load</b> = <b>1.5 × limit load</b>. The structure must carry limit load without permanent deformation and ultimate load without failing.","m":["\\text{Ultimate load}=1.5\\times\\text{limit load}"],"id":"cb3d1486d","s":"tec"},{"t":"tec-powerplant","f":"Four-stroke piston cycle?","a":"Intake, compression, power, exhaust: “suck, squeeze, bang, blow”.","l":["Two crankshaft turns per cycle","Dual magnetos for safety and efficiency","Rich mixture cools; lean peak EGT gives best economy"],"d":"otto","id":"c6fdffd3e","s":"tec"},{"t":"tec-powerplant","f":"Detonation, pre-ignition and fuel?","a":"<b>Detonation</b>: uncontrolled explosive burn after normal ignition. <b>Pre-ignition</b>: fuel ignites before the spark.","l":["Avgas 100LL is blue; avgas 100 green","Jet A-1: freezing point −47 °C or below","Low-octane fuel in a high-compression engine invites detonation"],"id":"c3aa6211a","s":"tec"},{"t":"tec-powerplant","f":"How does a gas turbine produce thrust?","a":"It accelerates a mass of air rearwards (Brayton cycle: intake, compression, combustion, exhaust).","l":["Turbofans accelerate a large mass by a small amount: more efficient","Thrust falls with altitude as density falls"],"m":["F=\\dot m\\,(V_e-V_0)","BPR=\\frac{\\dot m_{bypass}}{\\dot m_{core}}"],"id":"c29a3413b","s":"tec"},{"t":"tec-powerplant","f":"Compressor stall and surge?","a":"Airflow separates from the compressor blades, pressure falls and may reverse (a bang, vibration, flame from the intake).","l":["Caused by disturbed intake flow, rapid throttle movement or damage","Reduce power, check engine instruments"],"id":"c539ff4e7","s":"tec"},{"t":"tec-propellers","f":"Constant-speed propeller: how does it work?","a":"A governor changes blade pitch to keep RPM constant.","l":["Fine pitch (low angle): high RPM, take-off","Coarse pitch (high angle): low RPM, cruise","Feathering: blade turned to about 90° to stop windmilling after an engine failure"],"id":"c21faf614","s":"tec"},{"t":"tec-propellers","f":"Propeller effects on handling?","a":"Torque, slipstream, P-factor and gyroscopic precession all produce yaw or roll tendencies.","l":["P-factor: descending blade has a bigger angle of attack at high nose attitude, so yaw to the left for a clockwise-rotating propeller","Greater at low speed and high power"],"id":"c80f91378","s":"tec"},{"t":"tec-aircraft-systems","f":"Hydraulics: Pascal’s law?","a":"Pressure applied to a confined fluid is transmitted equally in all directions.","l":["Engine-driven or electric pumps, reservoir, accumulator, filters","Used for gear, flaps, brakes and flight controls"],"m":["P=\\frac{F}{A}"],"id":"cc8914af2","s":"tec"},{"t":"tec-aircraft-systems","f":"Pressurisation basics?","a":"Bleed air is conditioned, then the outflow valve controls cabin pressure.","l":["Cabin altitude is held at or below about 8000 ft","Safety valves protect against over- and negative pressure","Cabin altitude warning at about 10 000 ft; oxygen masks drop at about 14 000 ft"],"id":"c1e9eca9c","s":"tec"},{"t":"tec-aircraft-systems","f":"Aircraft electrical power?","a":"Generators or alternators supply AC; transformer-rectifier units convert to DC.","l":["Typical airliner: 115 V AC, 400 Hz and 28 V DC","Battery for starting and emergency","Constant-speed drive keeps frequency fixed"],"id":"ce1642aaa","s":"tec"},{"t":"tec-aircraft-systems","f":"Ice protection?","a":"Two approaches:","l":["<b>De-icing</b>: removes ice, for example pneumatic boots","<b>Anti-icing</b>: prevents ice forming, using bleed air or electric heating","Fluid systems (TKS) use glycol"],"id":"c44e3d464","s":"tec"},{"t":"tec-aircraft-systems","f":"Oxygen systems?","a":"Crew: gaseous. Passengers: chemical generators or gaseous, released when cabin altitude passes about 14 000 ft.","l":["Oxygen and oil or grease never mix","Know where the generator or cylinder is"],"id":"c9e951bbe","s":"tec"},{"t":"tec-pitot-statics","f":"How does the pitot-static system work?","a":"The pitot tube senses total pressure; static ports sense ambient pressure.","l":["ASI uses both","Altimeter and VSI use static only"],"m":["q=\\tfrac12\\rho V^2=p_{pitot}-p_{static}"],"d":"pitotstatic","id":"c8cf7e559","s":"tec"},{"t":"tec-pitot-statics","f":"What happens if the pitot tube blocks?","a":"ASI reads zero (drain open) or acts like an altimeter (drain blocked too): reading rises in a climb.","id":"c940c75fa","s":"tec"},{"t":"tec-pitot-statics","f":"What if the static source blocks?","a":"The altimeter freezes, the VSI reads zero, and the ASI is wrong in a climb or descent.","l":["ASI under-reads in a climb and over-reads in a descent","An alternate static source in the cabin makes the instruments read slightly high (altimeter high, ASI high, VSI shows a momentary climb)"],"id":"c897fbeab","s":"tec"},{"t":"tec-barometric-altimeters","f":"How does a barometric altimeter work?","a":"A stack of aneroid capsules expands as static pressure falls. Gears turn the pointers.","l":["Calibrated to ISA","Three pointers: 10 000 ft, 1000 ft, 100 ft","Subscale sets the reference pressure"],"id":"cca418df0","s":"tec"},{"t":"tec-barometric-altimeters","f":"List altimeter errors.","a":"Instrument, barometric, temperature, position and lag errors.","l":["Temperature error: about 4 ft per 1000 ft per °C","Hysteresis and lag after a rapid climb or descent","Mountain effect: Venturi in strong winds over ridges can lower static pressure"],"id":"c85d30aa6","s":"tec"},{"t":"tec-radio-altimeters","f":"How does a radio altimeter measure height?","a":"It transmits a radio signal downward and measures the time delay or frequency difference of the reflection.","l":["4.2–4.4 GHz FM-CW","Range up to about 2500 ft above ground level","Used for DH, GPWS and autoland"],"m":["h=\\frac{c\\,\\Delta t}{2}"],"d":"radalt","id":"c96be3a95","s":"tec"},{"t":"tec-radio-altimeters","f":"Radio altimeter versus barometric altimeter?","a":"The radio altimeter reads height <b>directly above the terrain</b> and responds to sudden changes; the barometric reads altitude above the pressure datum.","tip":"Steep terrain makes the radio altimeter jump.","id":"c6aed0f7d","s":"tec"},{"t":"tec-vertical-speed-indicators-vs","f":"How does a VSI work?","a":"Static pressure enters the capsule directly and the case through a calibrated leak. The pressure difference shows the rate.","l":["Lag of 6–9 s","IVSI uses accelerometer pistons to cut the lag","Reads zero if the static source blocks"],"id":"cbbe598f6","s":"tec"},{"t":"tec-airspeed-indicators","f":"ASI colour markings?","a":"<b>White</b> arc: flap range (VSO to VFE). <b>Green</b>: normal (VS1 to VNO). <b>Yellow</b>: caution (VNO to VNE). <b>Red</b> line: never exceed (VNE).","d":"asi","id":"c90046f44","s":"tec"},{"t":"tec-airspeed-indicators","f":"ASI construction and errors?","a":"A diaphragm connected to the pitot, case to the static.","l":["Instrument error, position (pressure) error, density error, compressibility error and lag","Position error is lower with the static source located correctly"],"id":"c3743295e","s":"tec"},{"t":"tec-airspeeds","f":"IAS, CAS, EAS and TAS?","a":"Corrections applied in order:","l":["IAS → CAS: instrument and position error","CAS → EAS: compressibility","EAS → TAS: density (altitude and temperature)","TAS ≈ CAS + 2 % per 1000 ft"],"m":["TAS=\\frac{EAS}{\\sqrt{\\sigma}},\\qquad\\sigma=\\frac{\\rho}{\\rho_0}"],"d":"speeds","id":"c4ffd0b26","s":"tec"},{"t":"tec-mach","f":"Local speed of sound and Mach number?","a":"The speed of sound depends only on temperature.","l":["ISA sea level: 661 kt","At or above 36 090 ft: 573 kt (−56.5 °C)","Mach angle: sin μ = 1 / M"],"m":["\\text{LSS}=38.95\\sqrt{T(\\text{K})}\\ \\text{kt}","M=\\frac{TAS}{\\text{LSS}}"],"d":"machcone","id":"c9b1d1749","s":"tec"},{"t":"tec-mach","f":"Critical Mach and compressibility effects?","a":"<b>MCRIT</b> is the free-stream Mach number at which local airflow first reaches Mach 1.","l":["Shock wave, wave drag, shock stall, Mach tuck","Sweepback and thin wings raise MCRIT","Mach trim compensates for tuck"],"id":"c5d9210fe","s":"tec"},{"t":"tec-mach","f":"What happens to IAS and Mach in climb and descent?","a":"In a constant-IAS climb, Mach increases. In a constant-Mach climb, IAS decreases.","l":["At the crossover altitude the speed reference changes from IAS to Mach (about FL 280–310)","VMO is an IAS limit, MMO a Mach limit"],"id":"c16c334cd","s":"tec"},{"t":"tec-gyroscope","f":"Two properties of a gyro?","a":"<b>Rigidity</b>: the spin axis stays fixed in space. <b>Precession</b>: a force applied to the rim acts 90° on in the direction of spin.","l":["Rigidity increases with mass, speed and radius","Rate gyros use precession; attitude and heading gyros use rigidity"],"d":"gyro","id":"c99613ed1","s":"tec"},{"t":"tec-gyroscope","f":"Drift and wander of a gyro?","a":"Earth rate gives an <b>apparent</b> drift; moving over the Earth adds <b>transport wander</b>.","l":["Zero earth-rate drift at the equator; 15°/h at the poles","Real drift comes from friction and imperfections"],"m":["\\text{Earth-rate drift}=15^\\circ/\\text{h}\\times\\sin\\phi","\\text{Transport wander}\\approx\\frac{V_{EW}\\tan\\phi}{60}\\ ^\\circ/\\text{h}"],"id":"c32100931","s":"tec"},{"t":"tec-gyroscope","f":"Types of gyro?","a":"Mechanical gyros, and ring-laser or fibre-optic gyros with no moving parts.","l":["Ring laser gyro uses the Sagnac effect","Directional gyro needs resetting to the compass about every 10–15 minutes"],"id":"c317dbc85","s":"tec"},{"t":"tec-attitude-indicators","f":"Attitude indicator: what does it show?","a":"Pitch and bank relative to the horizon, stabilised by an erect gyro.","l":["Acceleration error: a take-off roll gives an apparent climb indication","Turning error: small after a 180° turn","Older gyros topple at extreme attitudes"],"d":"ai","id":"c11682b20","s":"tec"},{"t":"tec-turn-and-slip","f":"Turn and slip or turn coordinator?","a":"A rate gyro shows rate of turn; the ball is an inclinometer for slip and skid.","l":["Standard (Rate 1) turn: 3° per second, 360° in 2 minutes","Ball in the middle: coordinated","Ball to the inside: slipping; to the outside: skidding","Turn coordinator senses roll as well as yaw"],"d":"turnslip","id":"c7bac2aee","s":"tec"},{"t":"tec-ins-irs-and-fms","f":"How does inertial navigation work?","a":"Accelerometers measure acceleration; integrating twice gives distance and position.","l":["Needs alignment on the ground, stationary, with known position","IRS uses ring-laser gyros (strapdown)","Position error grows with time, roughly 1–2 NM per hour","Schuler period 84.4 minutes"],"id":"c541bf6e2","s":"tec"},{"t":"tec-ins-irs-and-fms","f":"What does the FMS do?","a":"The flight management system holds the navigation and performance databases.","l":["Computes position from IRS, GPS and radio updates","Provides LNAV and VNAV guidance to the autopilot","Optimises speed using the cost index"],"id":"ca129071a","s":"tec"},{"t":"tec-efis","f":"EFIS colour conventions?","a":"Standard colours:","l":["<b>Green</b>: engaged modes and active information","<b>White</b>: scales and present values","<b>Magenta</b>: FMS flight plan and targets","<b>Cyan</b>: selected values and bugs","<b>Amber</b>: caution · <b>Red</b>: warning"],"id":"c605966c3","s":"tec"},{"t":"tec-efis","f":"Parts of EFIS?","a":"<b>PFD</b>: primary flight display. <b>ND</b>: navigation display.","l":["ND modes: ROSE, ARC, MAP, PLAN","Symbol generators drive the displays","Reversion lets one display take over"],"id":"c94da35a6","s":"tec"},{"t":"tec-autoflight","f":"Common autopilot modes?","a":"HDG, ALT, VS, LNAV, VNAV, LOC, APPR. The <b>FMA</b> shows what is engaged.","l":["Autothrottle manages thrust","Fail-passive autoland: two or more autopilots; fail-operational: three","Always monitor the FMA"],"id":"cff501a56","s":"tec"},{"t":"tec-flight-director","f":"What is the flight director?","a":"It displays pitch and roll <b>command bars</b>. Fly the aircraft to centre them.","l":["It does not control the aircraft by itself","Modes mirror those of the autopilot","Errors appear as bar displacement"],"id":"c68b353a6","s":"tec"},{"t":"tec-eicas-ecam","f":"EICAS and ECAM alert levels?","a":"Boeing EICAS and Airbus ECAM list alerts by severity:","l":["<b>Warning</b>: red, aural alert, immediate action","<b>Caution</b>: amber, attention","<b>Advisory</b>: no immediate action","<b>Memo</b>: white, status"],"tip":"ECAM shows engine and warning display on top, system display below.","id":"c332aefba","s":"tec"},{"t":"tec-engine-instruments","f":"Piston and turbine engine instruments?","a":"Piston: manifold pressure, RPM, oil pressure and temperature, CHT, EGT. Turbine: N1, N2, EPR, EGT/ITT, oil, vibration.","l":["Tachometer: magnetic or tacho-generator","N1 is the low-pressure spool; N2 the high-pressure"],"m":["EPR=\\frac{P_{t7}}{P_{t2}}"],"id":"c69877564","s":"tec"},{"t":"tec-temperature-indicators","f":"How is temperature measured in an engine?","a":"Thermocouples (two dissimilar metals) produce a voltage.","l":["EGT: chromel–alumel · CHT: iron–constantan","Resistance thermometers for oil and air temperature","Total air temperature includes ram rise"],"m":["\\frac{TAT}{SAT}=1+0.2\\,K\\,M^2\\quad(\\text{temperatures in K})"],"id":"c7b7430f4","s":"tec"},{"t":"tec-fuel-systems","f":"Fuel system essentials?","a":"Tanks, boost pumps, cross-feed, filters, and fuel heaters.","l":["Capacitance probes measure mass of fuel","Drain water from sumps before flight","Fuel jettison may reduce landing mass"],"id":"c6f427a6f","s":"tec"},{"t":"tec-compass","f":"Magnetic compass turning and acceleration errors?","a":"Dip makes the compass card tilt, which causes errors that depend on heading and latitude (northern hemisphere).","l":["<b>UNOS</b>: turning towards North, roll out before the compass reads north (undershoot); towards South, roll out after (overshoot)","<b>ANDS</b>: on an east or west heading, accelerating shows a turn towards north; decelerating shows a turn towards south","A compass swing finds deviation and the deviation card records it"],"d":"tvmdc","id":"c9867d419","s":"tec"},{"t":"tec-compass","f":"Remote-indicating compass?","a":"A flux valve senses the magnetic field and a gyro stabilises the heading.","l":["Mounted away from aircraft magnetism (wing tip)","Slaved gyro compass corrects for drift"],"id":"c11cd37a4","s":"tec"},{"t":"tec-warning-recording-systems","f":"GPWS modes?","a":"Classic GPWS monitors terrain proximity:","l":["1: excessive descent rate","2: excessive terrain closure rate","3: altitude loss after take-off","4: unsafe terrain clearance","5: below glideslope","6: callouts · 7: windshear"],"tip":"TAWS uses GPS and a terrain database to look ahead.","id":"c10ca52f9","s":"tec"},{"t":"tec-warning-recording-systems","f":"Stall warning and protection?","a":"A stick shaker warns of approaching stall; a stick pusher pushes the nose down if the stall is reached.","l":["Alpha floor: autothrottle sets full thrust","Take-off configuration warning if flaps or trim are wrong"],"id":"c7fb2b54e","s":"tec"},{"t":"tec-tcas","f":"TCAS symbols?","a":"On the display:","l":["<b>Other traffic</b>: hollow diamond","<b>Proximate</b>: filled diamond","<b>TA</b> (traffic advisory): amber filled circle","<b>RA</b> (resolution advisory): red filled square"],"d":"tcas","id":"cff7885e3","s":"tec"},{"t":"tec-tcas","f":"What does TCAS do?","a":"It warns of conflicting traffic using transponder replies.","l":["TCAS I: traffic advisories only","TCAS II: TA and vertical RAs","Operates on 1030/1090 MHz and needs the other aircraft to have a transponder","On an RA, follow it, even if it differs from ATC, and tell ATC"],"id":"c0d55e506","s":"tec"}]};